// Package harden is what a program generated by
// embedded.GenerateEmbeddedProgram uses to survive faults in memory, such
// as bit flips from radiation: a checksum of the program image checked a
// slice per scan (Scrubber), a repair of the VM's shared TRUE and FALSE
// (RepairSingletons), and RETAIN variables kept in two checksummed copies
// (Retain).
package harden

import (
	"cmp"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"math"
	"slices"
	"strings"
	"time"

	"github.com/apiarytech/beedance/compiler"
	"github.com/apiarytech/beedance/object"
	"github.com/apiarytech/beedance/vm"
)

// ErrImage is the error of a scan after which the program image (its
// instructions and constants) no longer matches its checksum.
var ErrImage = errors.New("harden: program image corrupt")

// ErrSingletons is the error of a scan after which the VM's shared TRUE
// or FALSE had changed value. RepairSingletons has set them back.
var ErrSingletons = errors.New("harden: TRUE or FALSE corrupt")

// Value tags of the encoding Checksum and Retain share.
const (
	tagBool byte = iota + 1
	tagSInt
	tagInt
	tagDInt
	tagLInt
	tagUSInt
	tagUInt
	tagUDInt
	tagULInt
	tagReal
	tagLReal
	tagByte
	tagWord
	tagDWord
	tagLWord
	tagBitString
	tagString
	tagWString
	tagTime
	tagDate
	tagTimeOfDay
	tagDateAndTime
	tagArray
	tagHash
	tagNull
	tagFunction
	// tagSkip stands for a value of a type the encoding does not cover.
	tagSkip byte = 0xFF
)

func appendU64(b []byte, v uint64) []byte { return binary.LittleEndian.AppendUint64(b, v) }
func appendU32(b []byte, v uint32) []byte { return binary.LittleEndian.AppendUint32(b, v) }

func appendString(b []byte, s string) []byte {
	return append(appendU32(b, uint32(len(s))), s...)
}

// appendValue appends the encoding of o to b. A value of a type it does
// not cover is tagSkip; ok reports whether all of o was covered.
func appendValue(b []byte, o object.Object) (_ []byte, ok bool) {
	switch v := o.(type) {
	case nil, *object.Null:
		return append(b, tagNull), true
	case *object.Boolean:
		if v.Value {
			return append(b, tagBool, 1), true
		}
		return append(b, tagBool, 0), true
	case *object.SInt:
		return appendU64(append(b, tagSInt), uint64(v.Value)), true
	case *object.Int:
		return appendU64(append(b, tagInt), uint64(v.Value)), true
	case *object.DInt:
		return appendU64(append(b, tagDInt), uint64(v.Value)), true
	case *object.LInt:
		return appendU64(append(b, tagLInt), uint64(v.Value)), true
	case *object.USInt:
		return appendU64(append(b, tagUSInt), uint64(v.Value)), true
	case *object.UInt:
		return appendU64(append(b, tagUInt), uint64(v.Value)), true
	case *object.UDInt:
		return appendU64(append(b, tagUDInt), uint64(v.Value)), true
	case *object.ULInt:
		return appendU64(append(b, tagULInt), v.Value), true
	case *object.Real:
		return appendU64(append(b, tagReal), math.Float64bits(v.Value)), true
	case *object.LReal:
		return appendU64(append(b, tagLReal), math.Float64bits(v.Value)), true
	case *object.Byte:
		return appendU64(append(b, tagByte), uint64(v.Value)), true
	case *object.Word:
		return appendU64(append(b, tagWord), uint64(v.Value)), true
	case *object.DWord:
		return appendU64(append(b, tagDWord), uint64(v.Value)), true
	case *object.LWord:
		return appendU64(append(b, tagLWord), v.Value), true
	case *object.BitString:
		return appendU64(append(b, tagBitString, byte(v.Width)), v.Value), true
	case *object.String:
		return appendString(append(b, tagString), v.Value), true
	case *object.WString:
		return appendString(append(b, tagWString), v.Value), true
	case *object.Time:
		return appendU64(append(b, tagTime), uint64(v.Value)), true
	case *object.Date:
		y, m, d := v.Value.Date()
		return append(appendU32(append(b, tagDate), uint32(y)), byte(m), byte(d)), true
	case *object.TimeOfDay:
		return appendU64(append(b, tagTimeOfDay), uint64(v.Value.UnixNano())), true
	case *object.DateAndTime:
		return appendU64(append(b, tagDateAndTime), uint64(v.Value.UnixNano())), true
	case *object.Array:
		b = appendU32(appendU64(append(b, tagArray), uint64(v.LowerBound)), uint32(len(v.Elements)))
		ok = true
		for _, e := range v.Elements {
			var eok bool
			b, eok = appendValue(b, e)
			ok = ok && eok
		}
		return b, ok
	case *object.Hash:
		keys := sortedKeys(v)
		b = appendU32(append(b, tagHash), uint32(len(keys)))
		ok = true
		for _, k := range keys {
			b = appendU64(appendString(b, string(k.Type)), k.Value)
			var eok bool
			b, eok = appendValue(b, v.Pairs[k].Value)
			ok = ok && eok
		}
		return b, ok
	}
	return append(b, tagSkip), false
}

// sortedKeys are h's keys in a fixed order.
func sortedKeys(h *object.Hash) []object.HashKey {
	keys := make([]object.HashKey, 0, len(h.Pairs))
	for k := range h.Pairs {
		keys = append(keys, k)
	}
	slices.SortFunc(keys, func(a, b object.HashKey) int {
		if c := strings.Compare(string(a.Type), string(b.Type)); c != 0 {
			return c
		}
		return cmp.Compare(a.Value, b.Value)
	})
	return keys
}

// segment is a run of bytes a checksum reads: instructions, in place, so
// that a scrub reads the memory the VM runs, or buf[lo:hi], the encoding
// of everything else.
type segment struct {
	live   []byte
	enc    bool
	lo, hi int
}

// appendFunction appends the encoding of what the generated code keeps of
// a compiled function, but its instructions.
func appendFunction(b []byte, fn *object.CompiledFunction) []byte {
	b = appendU32(appendU32(append(b, tagFunction), uint32(fn.NumLocals)), uint32(fn.NumParameters))
	for _, names := range [][]string{fn.ParameterNames, fn.OutputNames} {
		b = appendU32(b, uint32(len(names)))
		for _, n := range names {
			b = appendString(b, n)
		}
	}
	b = appendU32(b, uint32(len(fn.OutputIndices)))
	for _, i := range fn.OutputIndices {
		b = appendU64(b, uint64(i))
	}
	return appendU32(b, uint32(len(fn.Instructions)))
}

// appendSegments appends to segs, and to buf, what a checksum of bcs
// reads. Given the slices of an earlier call, cut to length 0, it
// allocates nothing more for the same image (but for structs among the
// constants).
func appendSegments(segs []segment, buf []byte, bcs []*compiler.Bytecode) ([]segment, []byte) {
	lo := len(buf)
	flush := func() {
		if len(buf) > lo {
			segs = append(segs, segment{enc: true, lo: lo, hi: len(buf)})
			lo = len(buf)
		}
	}
	for _, bc := range bcs {
		if bc == nil {
			continue
		}
		flush()
		segs = append(segs, segment{live: bc.Instructions})
		buf = appendU32(buf, uint32(len(bc.Constants)))
		for _, c := range bc.Constants {
			fn, ok := c.(*object.CompiledFunction)
			if !ok {
				buf, _ = appendValue(buf, c)
				continue
			}
			buf = appendFunction(buf, fn)
			flush()
			segs = append(segs, segment{live: fn.Instructions})
		}
	}
	flush()
	return segs, buf
}

func (s segment) bytes(buf []byte) []byte {
	if s.enc {
		return buf[s.lo:s.hi]
	}
	return s.live
}

// Checksum returns the CRC-32 (IEEE) of a program image: the bytecodes'
// instructions and constants, in order. Of a compiled function it covers
// what embedded's generated code keeps: not its name, lines or local names.
func Checksum(bcs ...*compiler.Bytecode) uint32 {
	segs, buf := appendSegments(nil, nil, bcs)
	var crc uint32
	for _, s := range segs {
		crc = crc32.Update(crc, crc32.IEEETable, s.bytes(buf))
	}
	return crc
}

// Scrubber checks a program image against its checksum a few bytes at a
// time, so that a scan pays a small, bounded cost and the whole image is
// read every few scans. The instructions are read where the VM runs them;
// the constants are encoded afresh at the start of each pass, into buffers
// kept from pass to pass, so a pass allocates nothing.
type Scrubber struct {
	want uint32
	bcs  []*compiler.Bytecode
	segs []segment
	buf  []byte
	pass bool // a pass is under way
	seg  int
	off  int
	crc  uint32
}

// NewScrubber returns a Scrubber of the image bcs, which should checksum
// to want.
func NewScrubber(want uint32, bcs ...*compiler.Bytecode) *Scrubber {
	return &Scrubber{want: want, bcs: bcs}
}

// Step reads the next n bytes of the image (at least 1). When it reads the
// last, a pass is done: Step reports done, and ok when the pass matched the
// checksum; the next Step starts a new pass. Before then it reports
// done false and ok true.
func (s *Scrubber) Step(n int) (done, ok bool) {
	if !s.pass {
		s.segs, s.buf = appendSegments(s.segs[:0], s.buf[:0], s.bcs)
		s.pass, s.seg, s.off, s.crc = true, 0, 0, 0
	}
	n = max(n, 1)
	for n > 0 && s.seg < len(s.segs) {
		seg := s.segs[s.seg].bytes(s.buf)
		k := min(n, len(seg)-s.off)
		s.crc = crc32.Update(s.crc, crc32.IEEETable, seg[s.off:s.off+k])
		s.off += k
		n -= k
		if s.off == len(seg) {
			s.seg, s.off = s.seg+1, 0
		}
	}
	if s.seg < len(s.segs) {
		return false, true
	}
	s.pass = false
	return true, s.crc == s.want
}

// RepairSingletons sets the VM's shared vm.True and vm.False back to true
// and false, which every BOOL of a program points to, and reports whether
// either had changed.
func RepairSingletons() bool {
	bad := !vm.True.Value || vm.False.Value
	vm.True.Value, vm.False.Value = true, false
	return bad
}

// decoder reads values appendValue wrote.
type decoder struct {
	b   []byte
	err bool
}

func (d *decoder) next(n int) []byte {
	if d.err || len(d.b) < n {
		d.err = true
		return make([]byte, n)
	}
	p := d.b[:n]
	d.b = d.b[n:]
	return p
}

func (d *decoder) u64() uint64 { return binary.LittleEndian.Uint64(d.next(8)) }
func (d *decoder) u32() uint32 { return binary.LittleEndian.Uint32(d.next(4)) }
func (d *decoder) u8() byte    { return d.next(1)[0] }
func (d *decoder) str() string {
	n := d.u32()
	if int(n) > len(d.b) {
		d.err = true
		return ""
	}
	return string(d.next(int(n)))
}

// value reads a value of the type of like, the variable's value as the
// program initialized it, and returns it as a new object. A tagSkip, in
// whole or in part, leaves like's value there. ok is false when the data
// does not have like's type or shape.
func (d *decoder) value(like object.Object) (_ object.Object, ok bool) {
	want, _ := appendValue(nil, like)
	tag := d.u8()
	if d.err {
		return nil, false
	}
	if tag == tagSkip {
		return like, true
	}
	if tag != want[0] {
		return nil, false
	}
	switch v := like.(type) {
	case nil, *object.Null:
		return like, true
	case *object.Boolean:
		if d.u8() != 0 {
			return vm.True, true
		}
		return vm.False, true
	case *object.SInt:
		return &object.SInt{Value: int8(d.u64())}, true
	case *object.Int:
		return &object.Int{Value: int16(d.u64())}, true
	case *object.DInt:
		return &object.DInt{Value: int32(d.u64())}, true
	case *object.LInt:
		return &object.LInt{Value: int64(d.u64())}, true
	case *object.USInt:
		return &object.USInt{Value: uint8(d.u64())}, true
	case *object.UInt:
		return &object.UInt{Value: uint16(d.u64())}, true
	case *object.UDInt:
		return &object.UDInt{Value: uint32(d.u64())}, true
	case *object.ULInt:
		return &object.ULInt{Value: d.u64()}, true
	case *object.Real:
		return &object.Real{Value: math.Float64frombits(d.u64())}, true
	case *object.LReal:
		return &object.LReal{Value: math.Float64frombits(d.u64())}, true
	case *object.Byte:
		return &object.Byte{Value: byte(d.u64())}, true
	case *object.Word:
		return &object.Word{Value: uint16(d.u64())}, true
	case *object.DWord:
		return &object.DWord{Value: uint32(d.u64())}, true
	case *object.LWord:
		return &object.LWord{Value: d.u64()}, true
	case *object.BitString:
		w := int(d.u8())
		if w != v.Width {
			return nil, false
		}
		return &object.BitString{Width: w, Value: d.u64()}, true
	case *object.String:
		return &object.String{Value: d.str()}, true
	case *object.WString:
		return &object.WString{Value: d.str()}, true
	case *object.Time:
		return &object.Time{Value: time.Duration(d.u64())}, true
	case *object.Date:
		y, m, day := int(int32(d.u32())), time.Month(d.u8()), int(d.u8())
		return &object.Date{Value: time.Date(y, m, day, 0, 0, 0, 0, v.Value.Location())}, true
	case *object.TimeOfDay:
		return &object.TimeOfDay{Value: time.Unix(0, int64(d.u64())).In(v.Value.Location())}, true
	case *object.DateAndTime:
		return &object.DateAndTime{Value: time.Unix(0, int64(d.u64())).In(v.Value.Location())}, true
	case *object.Array:
		lower, n := int64(d.u64()), int(d.u32())
		if lower != v.LowerBound || n != len(v.Elements) {
			return nil, false
		}
		out := &object.Array{LowerBound: lower, Elements: make([]object.Object, n)}
		for i, e := range v.Elements {
			if out.Elements[i], ok = d.value(e); !ok {
				return nil, false
			}
		}
		return out, true
	case *object.Hash:
		keys := sortedKeys(v)
		if int(d.u32()) != len(keys) {
			return nil, false
		}
		out := &object.Hash{Pairs: make(map[object.HashKey]object.HashPair, len(keys))}
		for _, k := range keys {
			if object.ObjectType(d.str()) != k.Type || d.u64() != k.Value {
				return nil, false
			}
			p := v.Pairs[k]
			val, ok := d.value(p.Value)
			if !ok {
				return nil, false
			}
			out.Pairs[k] = object.HashPair{Key: p.Key, Value: val}
		}
		return out, true
	}
	return nil, false
}
